const j = $json;

const chunkText = String(j.ChunkText ?? '');

return [{
  json: {
    ...j,

    debug: {
      TextID: j.TextID ?? null,
      TextTyp: j.TextTyp ?? null,
      TextUUID: j.TextUUID ?? null,
      ChunkUUID: j.ChunkUUID ?? null,
      ChunkChunkNumber: j.ChunkChunkNumber ?? null,

      ChunkChars: chunkText.length,

      ChunkPreviewStart: chunkText.slice(0, 500),
      ChunkPreviewEnd: chunkText.slice(-300),

      HasChunkText: chunkText.trim().length > 0,

      PromptChars: Math.min(chunkText.length, 12000),

      IsBFEE: j.TextTyp === 'BFEE'
    }
  }
}];

const j = $json;

const raw = String(j.message?.content ?? '');

return [{
  json: {
    ...j,

    debugOllama: {
      Model: j.model ?? null,
      DoneReason: j.done_reason ?? null,
      PromptTokens: j.prompt_eval_count ?? null,
      OutputTokens: j.eval_count ?? null,
      TotalDurationNs: j.total_duration ?? null,

      HasMessageContent: raw.trim().length > 0,
      RawLength: raw.length,
      RawPreviewStart: raw.slice(0, 1500),
      RawPreviewEnd: raw.slice(-1000)
    }
  }
}];

const response = $json;
const source = $('Code - debug identifier input').first().json;

const allowedTypes = new Set([
  'article_number',
  'offer_number',
  'invoice_number',
  'customer_number',
  'order_number',
  'purchase_order_number',
  'delivery_note_number',
  'supplier_number',
  'material_number',
  'contract_number',
  'project_number',
  'account_number',

  'serial_number',
  'batch_number',
  'lot_number',
  'gtin',
  'ean',
  'udi',
  'udi_di',
  'catalog_number',

  'document_number',
  'sop_number',
  'work_instruction_number',
  'form_number',
  'policy_number',
  'specification_number',
  'protocol_number',
  'report_number',
  'procedure_number',
  'template_number',
  'quality_record_number',

  'law_reference',
  'regulation_reference',
  'directive_reference',
  'legal_section_reference',
  'standard_reference',
  'guideline_reference',
  'regulatory_document_reference',

  'doi',
  'pmid',
  'patent_number',
  'clinical_trial_number',
  'publication_reference',

  'vat_id',
  'tax_number',
  'iban',
  'bic',
  'case_number',
  'file_number',
  'reference_number',
  'external_reference'
]);

const allowedRoles = new Set([
  'document_identifier',
  'reference',
  'mention'
]);

function clean(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeValue(value) {
  return clean(value).toLocaleLowerCase('de-DE');
}

function makeMatchKey(type, value) {
  const normalized = normalizeValue(value)
    .replace(/\s*([:/()])\s*/g, '$1')
    .replace(/\s*-\s*/g, '-');

  return `${type}:${normalized}`.slice(0, 300);
}

/* ---------------------------------------------------------
 * Ollama JSON
 * --------------------------------------------------------- */

let rawContent = response.message?.content;

if (typeof rawContent !== 'string' || !rawContent.trim()) {
  throw new Error('Ollama hat kein message.content geliefert.');
}

rawContent = rawContent
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(rawContent);
} catch (error) {
  return [{
    json: {
      ChunkUUID: source.ChunkUUID,
      TextUUID: source.TextUUID,
      TextID: source.TextID,
      TextTyp: source.TextTyp,
      ChunkChunkNumber: source.ChunkChunkNumber,

      validationPassed: false,
      retryable: true,
      validationError: 'INVALID_OR_TRUNCATED_JSON',

      parseError: error.message,

      model: String(response.model ?? ''),
      ollamaDoneReason: response.done_reason ?? null,
      ollamaPromptTokens: response.prompt_eval_count ?? null,
      ollamaOutputTokens: response.eval_count ?? null,

      rawModelOutput: rawContent
    }
  }];
}

const candidates = Array.isArray(parsed.identifiers)
  ? parsed.identifiers
  : [];

const chunkTextOriginal = String(source.ChunkText ?? '');
const chunkTextNormalized = clean(chunkTextOriginal);

const identifiers = [];
const rejectedIdentifiers = [];
const seen = new Set();

/* ---------------------------------------------------------
 * Deterministische Validierung
 * --------------------------------------------------------- */

for (const candidate of candidates) {
  const type = clean(candidate.type);
  const role = clean(candidate.role);
  const value = clean(candidate.value);
  const label = clean(candidate.label);
  const issuer = clean(candidate.issuer);
  const context = clean(candidate.context);

  const reasons = [];

  if (!allowedTypes.has(type)) {
    reasons.push('INVALID_TYPE');
  }

  if (!allowedRoles.has(role)) {
    reasons.push('INVALID_ROLE');
  }

  if (!value) {
    reasons.push('EMPTY_VALUE');
  }

  // value muss im Original oder whitespace-normalisiert vorkommen
  if (
    value &&
    !chunkTextOriginal.includes(value) &&
    !chunkTextNormalized.includes(value)
  ) {
    reasons.push('VALUE_NOT_GROUNDED');
  }

  // context muss value enthalten
  if (context && !context.includes(value)) {
    reasons.push('CONTEXT_DOES_NOT_CONTAIN_VALUE');
  }

  // context muss aus dem Chunk stammen
  if (
    context &&
    !chunkTextOriginal.includes(context) &&
    !chunkTextNormalized.includes(context)
  ) {
    reasons.push('CONTEXT_NOT_GROUNDED');
  }

  const normalizedValue = normalizeValue(value);
  const matchKey = makeMatchKey(type, value);

  const duplicateKey = `${type}|${role}|${normalizedValue}`;

  if (seen.has(duplicateKey)) {
    reasons.push('DUPLICATE');
  }

  if (reasons.length > 0) {
    rejectedIdentifiers.push({
      type,
      role,
      value,
      label,
      issuer,
      context,
      reasons
    });

    continue;
  }

  seen.add(duplicateKey);

  identifiers.push({
    type,
    role,
    value,
    normalizedValue,
    matchKey,
    label,
    issuer,
    context
  });
}

/* ---------------------------------------------------------
 * Ergebnis
 * --------------------------------------------------------- */

const extractionJSON = {
  identifiers,
  rejectedIdentifiers,
  validation: {
    errors: [],
    warnings: rejectedIdentifiers.length
      ? [
          `${rejectedIdentifiers.length} Kandidat(en) durch deterministische Validierung verworfen`
        ]
      : []
  },
  rawModelOutput: rawContent
};

return [{
  json: {
    ChunkUUID: source.ChunkUUID,
    TextUUID: source.TextUUID,
    TextID: source.TextID,
    TextTyp: source.TextTyp,
    ChunkChunkNumber: source.ChunkChunkNumber,

    model: String(response.model ?? ''),
    schemaVersion: '1.0',

    identifierCount: identifiers.length,
    groundingChecked: true,
    validationPassed: true,

    identifiers,
    rejectedIdentifiers,

    ExtractionJSON: JSON.stringify(extractionJSON),

    debugValidation: {
      CandidateCount: candidates.length,
      AcceptedCount: identifiers.length,
      RejectedCount: rejectedIdentifiers.length
    },

    ollamaDoneReason: response.done_reason ?? null,
    ollamaPromptTokens: response.prompt_eval_count ?? null,
    ollamaOutputTokens: response.eval_count ?? null,
    ollamaTotalDurationNs: response.total_duration ?? null
  }
}];

